import{_ as o}from"./plugin-vue_export-helper-c27b6911.js";import{r as c,o as i,c as d,d as s,e as n,a as e,w as t,f as p}from"./app-5011595d.js";const l={},r=s("h1",{id:"指向分析-points-to-analysis",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#指向分析-points-to-analysis","aria-hidden":"true"},"#"),n(" 指向分析（Points-to Analysis）")],-1),u=s("p",null,"指针可以指向局部变量、全局变量或动态分配的对象，还可以通过其他指针间接读写。编译器如果不知道一次间接访问可能涉及哪些内存，就只能保守地保留许多加载、存储和函数调用。",-1),k=s("strong",null,[n("指针分析（Pointer Analysis）"),s("strong",null,"是研究这些访问关系的一类分析。本节重点介绍其中的"),n("指向分析")],-1),v=p(`<p>本节从指向集合开始，介绍基于包含约束的 Andersen 分析、基于合一的 Steensgaard 分析，以及精度与代价之间的取舍，最后实现一个简化的约束求解器。</p><h2 id="从具体地址到抽象对象" tabindex="-1"><a class="header-anchor" href="#从具体地址到抽象对象" aria-hidden="true">#</a> 从具体地址到抽象对象</h2><p>程序运行时，指针保存的是具体地址；静态分析通常不追踪每次执行的地址，而是用<strong>抽象内存对象</strong>表示一组可能的存储位置。</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> x <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token operator">&amp;</span>x<span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>q <span class="token operator">=</span> p<span class="token punctuation">;</span>
q <span class="token operator">=</span> <span class="token operator">&amp;</span>y<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们用 <code>o_x</code>、<code>o_y</code> 表示变量 <code>x</code>、<code>y</code> 对应的对象，用 <code>pt(p)</code> 表示指针 <code>p</code> 的指向集合。分析结果取决于是否区分语句的执行顺序：</p><ul><li>如果追踪每个程序点，最后一行之后可以得到 <code>pt(p) = {o_x}</code>，<code>pt(q) = {o_y}</code>。</li><li>如果把整个函数中的约束统一求解，不区分程序点，通常得到 <code>pt(p) = {o_x}</code>，<code>pt(q) = {o_x, o_y}</code>。</li></ul><p>第二种结果不够精确，但仍然包含所有实际可能的目标。这样的“可能指向”分析通常称为 <strong>may-points-to 分析</strong>。</p><p>静态分析要求保守：可以多包含一些实际上不会出现的目标，不能遗漏可能发生的访问。对于无法建模的外部输入、未知函数或地址运算，需要使用未知对象等保守表示，不能直接把它们当作空集合。</p><h3 id="对象怎样划分" tabindex="-1"><a class="header-anchor" href="#对象怎样划分" aria-hidden="true">#</a> 对象怎样划分</h3><table><thead><tr><th>内存来源</th><th>常见抽象方式</th><th>可能损失的信息</th></tr></thead><tbody><tr><td>局部变量、全局变量</td><td>每个变量对应一个对象</td><td>跨调用合并局部对象时可能丢失调用区别</td></tr><tr><td><code>malloc</code> 等动态分配</td><td>每个分配位置对应一个对象</td><td>同一位置在不同执行次数中分配的对象被合并</td></tr><tr><td>结构体</td><td>每个结构体一个对象，或每个字段一个子对象</td><td>不区分字段时，成员访问容易互相干扰</td></tr><tr><td>数组</td><td>整个数组一个对象，或按元素、区间划分</td><td>合并元素时无法区分不同下标</td></tr></tbody></table><p>例如循环中的同一个 <code>malloc</code> 调用可以创建上千个对象，按分配位置抽象会把它们归入一个抽象对象。这使集合保持有限，也引入了额外的可能关系。</p><h2 id="指向集合如何帮助判断别名" tabindex="-1"><a class="header-anchor" href="#指向集合如何帮助判断别名" aria-hidden="true">#</a> 指向集合如何帮助判断别名</h2><p>考虑只包含完整标量对象、没有字段偏移的简化模型：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>pt(p) = {o_x}
pt(q) = {o_x, o_y}
pt(r) = {o_z}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>p</code> 与 <code>q</code> 的集合相交，因此可能别名；<code>p</code> 与 <code>r</code> 的集合不相交，因此在该模型下可以判定不别名。</p><p>集合相交并不能直接证明“一定别名”。例如 <code>p</code> 与 <code>q</code> 可能分别来自互斥分支，不同路径上的关系在合并时会丢失。即使两个集合都是同一个抽象堆对象，也可能只是指向同一分配位置产生的不同运行时对象。</p><p>真实编译器还需要考虑访问大小、字段偏移和对象重叠。两个指针指向同一个结构体，并不代表对不同字段的访问会冲突。因此，指向集合是别名查询的输入之一，而不是所有别名结论的完整替代。</p><h2 id="基于包含约束的-andersen-分析" tabindex="-1"><a class="header-anchor" href="#基于包含约束的-andersen-分析" aria-hidden="true">#</a> 基于包含约束的 Andersen 分析</h2><p>Andersen 分析把指针操作转换为集合包含关系，再不断传播目标，直到所有约束都满足。经典形式通常是流不敏感、上下文不敏感的；这些是常见配置，不代表包含约束只能用于这一种精度。</p><p>为了先看清核心算法，我们只考虑四种规范化语句：取地址、复制、间接加载和间接存储。复杂表达式可以先拆成临时变量上的简单操作。</p><h3 id="四种基本约束" tabindex="-1"><a class="header-anchor" href="#四种基本约束" aria-hidden="true">#</a> 四种基本约束</h3><table><thead><tr><th>语句</th><th>含义</th><th>约束</th></tr></thead><tbody><tr><td><code>p = &amp;x</code></td><td>取对象地址</td><td><code>o_x ∈ pt(p)</code></td></tr><tr><td><code>p = q</code></td><td>复制指针</td><td><code>pt(q) ⊆ pt(p)</code></td></tr><tr><td><code>p = *q</code></td><td>从 <code>q</code> 指向的对象中读取指针</td><td>对每个 <code>o ∈ pt(q)</code>，<code>pt(o) ⊆ pt(p)</code></td></tr><tr><td><code>*p = q</code></td><td>向 <code>p</code> 指向的对象中写入指针</td><td>对每个 <code>o ∈ pt(p)</code>，<code>pt(q) ⊆ pt(o)</code></td></tr></tbody></table><p>这里需要区分两层含义：<code>o_x</code> 表示变量 <code>x</code> 的存储位置；如果 <code>x</code> 自身存放指针，<code>pt(o_x)</code> 就表示这个位置中可能保存的指针目标。非指针对象没有需要传播的指针内容。</p><p>直接指针变量可以视为其存储对象的简写：后面的求解器把 <code>p</code> 同时用作变量节点和该变量的存储对象标识，以便演示 <code>&amp;p</code> 和间接访问之间的联系。实际实现也可以将变量值节点与内存对象节点分开，并显式连接读写关系。</p><h3 id="一个包含二级指针的例子" tabindex="-1"><a class="header-anchor" href="#一个包含二级指针的例子" aria-hidden="true">#</a> 一个包含二级指针的例子</h3><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> x <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token operator">&amp;</span>x<span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>q <span class="token operator">=</span> <span class="token operator">&amp;</span>y<span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span><span class="token operator">*</span>r <span class="token operator">=</span> <span class="token operator">&amp;</span>p<span class="token punctuation">;</span>
<span class="token operator">*</span>r <span class="token operator">=</span> q<span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>s <span class="token operator">=</span> <span class="token operator">*</span>r<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在上述简写下，初始的取地址约束为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>pt(p) 包含 x
pt(q) 包含 y
pt(r) 包含 p
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>接着处理间接存储 <code>*r = q</code>：因为 <code>r</code> 可能指向 <code>p</code>，所以添加 <code>pt(q) ⊆ pt(p)</code>，于是 <code>pt(p)</code> 增加 <code>y</code>。</p><p>处理间接加载 <code>s = *r</code> 时，同样沿着 <code>r -&gt; p</code> 找到保存指针的位置，再把 <code>pt(p)</code> 传播给 <code>pt(s)</code>。最终得到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>pt(p) = {x, y}
pt(q) = {y}
pt(r) = {p}
pt(s) = {x, y}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>按顺序执行这段程序，最后的 <code>p</code> 和 <code>s</code> 实际只指向 <code>y</code>。流不敏感分析保留 <code>x</code>，因为它同时考虑了对 <code>p</code> 的初始赋值和后续写入。这个额外目标来自分析抽象，而不是程序真的在最后保留了两个地址。</p><h3 id="为什么要反复传播" tabindex="-1"><a class="header-anchor" href="#为什么要反复传播" aria-hidden="true">#</a> 为什么要反复传播</h3><p>间接访问产生的关系取决于其他集合。例如处理 <code>s = *r</code> 时，如果尚不知道 <code>r</code> 指向 <code>p</code>，就无法立即发现从 <code>p</code> 到 <code>s</code> 的传播关系。</p><p>所以不能只扫描语句一次。一个简单实现是反复扫描全部约束，每次只向集合中增加元素，直到没有集合发生变化。由于节点和对象数量有限，集合只增不减，这个过程最终终止。由空集合出发，得到的是满足这些包含约束的最小不动点。</p><p>图与约束在这里不是互斥路线：取地址关系可以表示为指向边，<code>pt(q) ⊆ pt(p)</code> 可以表示为从 <code>q</code> 到 <code>p</code> 的复制边。加载和存储在发现新指向目标后，会产生新的传播关系。图是组织和求解约束的一种方式。</p><h2 id="实验-实现一个简化求解器" tabindex="-1"><a class="header-anchor" href="#实验-实现一个简化求解器" aria-hidden="true">#</a> 实验：实现一个简化求解器</h2><p>下面的 Python 程序实现上述四类约束。它忽略控制流、字段、堆分配、空指针和函数调用，输入是假定已通过类型检查的规范化操作。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> collections <span class="token keyword">import</span> defaultdict


<span class="token keyword">def</span> <span class="token function">solve</span><span class="token punctuation">(</span>constraints<span class="token punctuation">)</span><span class="token punctuation">:</span>
    points_to <span class="token operator">=</span> defaultdict<span class="token punctuation">(</span><span class="token builtin">set</span><span class="token punctuation">)</span>
    changed <span class="token operator">=</span> <span class="token boolean">True</span>

    <span class="token keyword">def</span> <span class="token function">include</span><span class="token punctuation">(</span>dst<span class="token punctuation">,</span> values<span class="token punctuation">)</span><span class="token punctuation">:</span>
        before <span class="token operator">=</span> <span class="token builtin">len</span><span class="token punctuation">(</span>points_to<span class="token punctuation">[</span>dst<span class="token punctuation">]</span><span class="token punctuation">)</span>
        points_to<span class="token punctuation">[</span>dst<span class="token punctuation">]</span><span class="token punctuation">.</span>update<span class="token punctuation">(</span>values<span class="token punctuation">)</span>
        <span class="token keyword">return</span> <span class="token builtin">len</span><span class="token punctuation">(</span>points_to<span class="token punctuation">[</span>dst<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">!=</span> before

    <span class="token keyword">while</span> changed<span class="token punctuation">:</span>
        changed <span class="token operator">=</span> <span class="token boolean">False</span>
        <span class="token keyword">for</span> kind<span class="token punctuation">,</span> dst<span class="token punctuation">,</span> src <span class="token keyword">in</span> constraints<span class="token punctuation">:</span>
            <span class="token keyword">if</span> kind <span class="token operator">==</span> <span class="token string">&quot;addr&quot;</span><span class="token punctuation">:</span>          <span class="token comment"># dst = &amp;src</span>
                grew <span class="token operator">=</span> include<span class="token punctuation">(</span>dst<span class="token punctuation">,</span> <span class="token punctuation">{</span>src<span class="token punctuation">}</span><span class="token punctuation">)</span>
            <span class="token keyword">elif</span> kind <span class="token operator">==</span> <span class="token string">&quot;copy&quot;</span><span class="token punctuation">:</span>        <span class="token comment"># dst = src</span>
                grew <span class="token operator">=</span> include<span class="token punctuation">(</span>dst<span class="token punctuation">,</span> points_to<span class="token punctuation">[</span>src<span class="token punctuation">]</span><span class="token punctuation">)</span>
            <span class="token keyword">elif</span> kind <span class="token operator">==</span> <span class="token string">&quot;load&quot;</span><span class="token punctuation">:</span>        <span class="token comment"># dst = *src</span>
                grew <span class="token operator">=</span> <span class="token boolean">False</span>
                <span class="token keyword">for</span> obj <span class="token keyword">in</span> <span class="token builtin">tuple</span><span class="token punctuation">(</span>points_to<span class="token punctuation">[</span>src<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
                    grew <span class="token operator">=</span> include<span class="token punctuation">(</span>dst<span class="token punctuation">,</span> points_to<span class="token punctuation">[</span>obj<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">or</span> grew
            <span class="token keyword">elif</span> kind <span class="token operator">==</span> <span class="token string">&quot;store&quot;</span><span class="token punctuation">:</span>       <span class="token comment"># *dst = src</span>
                grew <span class="token operator">=</span> <span class="token boolean">False</span>
                <span class="token keyword">for</span> obj <span class="token keyword">in</span> <span class="token builtin">tuple</span><span class="token punctuation">(</span>points_to<span class="token punctuation">[</span>dst<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
                    grew <span class="token operator">=</span> include<span class="token punctuation">(</span>obj<span class="token punctuation">,</span> points_to<span class="token punctuation">[</span>src<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">or</span> grew
            <span class="token keyword">else</span><span class="token punctuation">:</span>
                <span class="token keyword">raise</span> ValueError<span class="token punctuation">(</span><span class="token string-interpolation"><span class="token string">f&quot;unknown constraint: </span><span class="token interpolation"><span class="token punctuation">{</span>kind<span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span>
            changed <span class="token operator">=</span> grew <span class="token keyword">or</span> changed

    <span class="token keyword">return</span> <span class="token punctuation">{</span>name<span class="token punctuation">:</span> <span class="token builtin">set</span><span class="token punctuation">(</span>targets<span class="token punctuation">)</span> <span class="token keyword">for</span> name<span class="token punctuation">,</span> targets <span class="token keyword">in</span> points_to<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">}</span>


constraints <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token punctuation">(</span><span class="token string">&quot;addr&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;p&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;x&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">(</span><span class="token string">&quot;addr&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;q&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;y&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">(</span><span class="token string">&quot;addr&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;r&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;p&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">(</span><span class="token string">&quot;store&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;r&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;q&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">(</span><span class="token string">&quot;load&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;s&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;r&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span>
result <span class="token operator">=</span> solve<span class="token punctuation">(</span>constraints<span class="token punctuation">)</span>
<span class="token keyword">for</span> name <span class="token keyword">in</span> <span class="token punctuation">(</span><span class="token string">&quot;p&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;q&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;r&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;s&quot;</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    <span class="token keyword">print</span><span class="token punctuation">(</span>name<span class="token punctuation">,</span> <span class="token builtin">sorted</span><span class="token punctuation">(</span>result<span class="token punctuation">[</span>name<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>p [&#39;x&#39;, &#39;y&#39;]
q [&#39;y&#39;]
r [&#39;p&#39;]
s [&#39;x&#39;, &#39;y&#39;]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>tuple(...)</code> 为本轮枚举建立快照，避免传播时集合增大导致迭代器失效；新增关系会在后续扫描中继续处理。每条约束都必须执行，不能因为本轮已经发现变化，就用短路求值跳过后面的传播。</p><p>这个实现便于理解，但会重复扫描没有变化的约束。实际实现常使用工作列表：集合增长时，只重新处理依赖该节点的约束，并尽量传播新增目标。需要特别注意，加载、存储的基址集合增长时，也必须重新建立或触发对应的传播关系。</p><p>读者可以尝试把 <code>load</code> 放到约束列表最前面，或增加 <code>p = s</code> 形成环。正确求解器仍应收敛到满足所有约束的结果，不能依赖语句在列表中的特定顺序。</p><h2 id="基于合一的-steensgaard-分析" tabindex="-1"><a class="header-anchor" href="#基于合一的-steensgaard-分析" aria-hidden="true">#</a> 基于合一的 Steensgaard 分析</h2><p>Andersen 分析在复制 <code>p = q</code> 时保留有方向的包含关系，允许 <code>p</code> 比 <code>q</code> 拥有更多目标。</p><p>Steensgaard 分析采用另一种思路：用等价类表示抽象位置及其指向关系，通过合一（Unification）合并需要统一的节点。这类算法通常使用并查集，经典算法可以达到近线性的时间复杂度，但合并之后难以再区分原来的目标。</p><p>例如下面的代码：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> x <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token operator">&amp;</span>x<span class="token punctuation">;</span>
<span class="token keyword">int</span> <span class="token operator">*</span>q <span class="token operator">=</span> <span class="token operator">&amp;</span>y<span class="token punctuation">;</span>
p <span class="token operator">=</span> q<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>流不敏感的包含分析允许：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>pt(p) = {x, y}
pt(q) = {y}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>在典型合一模型中，复制约束会促使相关指向关系合一，原本不同的目标可能被合并为同一抽象类。后续查询 <code>q</code> 时，也可能无法再排除 <code>x</code>。这里描述的是合一造成精度损失的直观效果，完整算法还需要处理地址、解引用和类型结构，不能只把所有赋值两端的变量无条件并在一起。</p><table><thead><tr><th>方法</th><th>核心关系</th><th>典型特点</th></tr></thead><tbody><tr><td>Andersen</td><td>集合包含</td><td>保留传播方向，通常更精确，求解代价可能较高</td></tr><tr><td>Steensgaard</td><td>等价与合一</td><td>借助并查集高效求解，合并容易引入额外目标</td></tr></tbody></table><p>在朴素表示下，经典 Andersen 求解的最坏复杂度可达立方量级；实际耗时仍取决于约束规模、集合表示和传播策略。不能仅凭算法名称判断某个工程实现的速度。</p><h2 id="如何提高分析精度" tabindex="-1"><a class="header-anchor" href="#如何提高分析精度" aria-hidden="true">#</a> 如何提高分析精度</h2><h3 id="流敏感-区分程序点" tabindex="-1"><a class="header-anchor" href="#流敏感-区分程序点" aria-hidden="true">#</a> 流敏感：区分程序点</h3><p>流不敏感分析把约束合在一起，通常只做<strong>弱更新</strong>：新增目标，不删除旧目标。流敏感分析则沿控制流传播状态，并在分支汇合处合并。</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token operator">&amp;</span>x<span class="token punctuation">;</span>
p <span class="token operator">=</span> <span class="token operator">&amp;</span>y<span class="token punctuation">;</span>
<span class="token comment">// 此处 p 只指向 y</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果能确认赋值覆盖了唯一的具体存储位置，可以进行<strong>强更新</strong>，用 <code>{y}</code> 替换旧集合。</p><p>对于 <code>*r = q</code>，只有证明被更新的是唯一具体对象，且写入覆盖相关指针位置时，才能安全删除该位置的旧目标。<code>pt(r)</code> 只有一个抽象对象还不一定足够：这个对象可能概括了多次分配产生的许多具体对象。此时通常仍需弱更新。</p><h3 id="上下文敏感-区分调用" tabindex="-1"><a class="header-anchor" href="#上下文敏感-区分调用" aria-hidden="true">#</a> 上下文敏感：区分调用</h3><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> <span class="token operator">*</span><span class="token function">identity</span><span class="token punctuation">(</span><span class="token keyword">int</span> <span class="token operator">*</span>p<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> p<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">void</span> <span class="token function">example</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> x <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> <span class="token operator">*</span>a <span class="token operator">=</span> <span class="token function">identity</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>x<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> <span class="token operator">*</span>b <span class="token operator">=</span> <span class="token function">identity</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>y<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">// a、b 在各自调用中分别指向 x、y</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上下文不敏感分析如果共用一份形参和返回值摘要，容易把两次调用的目标合并，导致 <code>a</code>、<code>b</code> 都被认为可能指向 <code>x</code> 或 <code>y</code>。上下文敏感分析可以按调用位置、有限长度的调用链等方式区分这两次调用，从而恢复精度。</p><p>上下文划分越细，需要维护的状态通常越多；递归也要求对上下文进行有限抽象，不能无限展开调用链。</p><h3 id="字段敏感-区分结构体成员" tabindex="-1"><a class="header-anchor" href="#字段敏感-区分结构体成员" aria-hidden="true">#</a> 字段敏感：区分结构体成员</h3><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">struct</span> <span class="token class-name">Pair</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> <span class="token operator">*</span>left<span class="token punctuation">;</span>
    <span class="token keyword">int</span> <span class="token operator">*</span>right<span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">void</span> <span class="token function">fields</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> x <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
    <span class="token keyword">struct</span> <span class="token class-name">Pair</span> pair<span class="token punctuation">;</span>
    pair<span class="token punctuation">.</span>left <span class="token operator">=</span> <span class="token operator">&amp;</span>x<span class="token punctuation">;</span>
    pair<span class="token punctuation">.</span>right <span class="token operator">=</span> <span class="token operator">&amp;</span>y<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>字段敏感分析为 <code>pair.left</code> 和 <code>pair.right</code> 建立不同位置，可以分别记录 <code>{x}</code> 和 <code>{y}</code>。字段不敏感分析把它们合并到整个结构体的抽象中，容易让两个成员都得到 <code>{x, y}</code>。</p><p>流敏感、上下文敏感和字段敏感是不同维度，可以组合使用。路径敏感分析还可以利用分支条件区分互斥路径，但通常需要更多计算资源。</p><h2 id="工程中还要处理什么" tabindex="-1"><a class="header-anchor" href="#工程中还要处理什么" aria-hidden="true">#</a> 工程中还要处理什么</h2><p>前面的求解器只展示了核心传播机制。面对 C/C++ 等语言，还需要扩展模型：</p><ul><li><strong>指针算术与数组</strong>：为偏移、下标和对象边界建立抽象；无法精确处理的偏移需要保守合并。</li><li><strong>函数指针与间接调用</strong>：由指向结果发现可能的被调函数，再传播实参、形参和返回值。新调用边又可能产生新目标，调用图和指向结果常需一起迭代。</li><li><strong>外部函数</strong>：为已知库函数提供摘要；未知函数可能读写可达内存、保存传入指针或返回未知地址，需要保守处理。</li><li><strong>堆与对象生命周期</strong>：按分配位置或上下文区分对象。发现可能指向某对象并不等于证明该对象仍然有效，还需要生命周期分析。</li><li><strong>整数与指针转换、联合体等操作</strong>：处理语言与目标平台允许的表示变化，避免因忽略访问方式而遗漏关系。</li></ul><p>空指针也不能与“求解尚未发现目标”混为一谈。如果需要诊断空指针解引用，模型通常要显式记录空值及其传播；未知指针则可能指向许多有效对象。两者不能统一用一个空集合代替。</p><h2 id="指向分析的应用与边界" tabindex="-1"><a class="header-anchor" href="#指向分析的应用与边界" aria-hidden="true">#</a> 指向分析的应用与边界</h2>`,73),m=p('<p>安全检查同样可以利用这些信息：可能的访问目标帮助定位空指针、释放后使用或内存泄漏风险。不过，仅靠指向集合不能证明没有越界、没有泄漏；还需要范围分析、生命周期分析或路径条件等信息。</p><p>例如，知道 <code>p</code> 指向数组 <code>a</code>，并不能回答 <code>p[i]</code> 是否越界；还必须知道数组长度、指针偏移和 <code>i</code> 的范围。分析结果提供证据，不应被解释为超出模型能力的安全保证。</p><h2 id="练习" tabindex="-1"><a class="header-anchor" href="#练习" aria-hidden="true">#</a> 练习</h2><ol><li>对 <code>p = &amp;x; q = p; p = &amp;y;</code> 分别写出流不敏感结果和最后一个程序点的流敏感结果，解释两者的差异。</li><li>在求解器中加入 <code>t = s</code>，并打乱约束顺序，验证结果不变；再加入一个没有取地址来源的复制环，观察其集合是否保持为空。</li><li>解释为什么 <code>pt(p) = pt(q) = {heap_site}</code> 不能直接证明 <code>p</code> 和 <code>q</code> 在运行时相等。</li><li>为简化求解器增加字段节点，例如 <code>pair.left</code> 和 <code>pair.right</code>，比较字段合并前后的目标集合。</li></ol><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结" aria-hidden="true">#</a> 小结</h2><p>指向分析用有限的抽象对象描述指针可能访问的内存。Andersen 分析通过包含约束传播集合，Steensgaard 分析通过合一降低求解成本；两者都需要在分析精度和计算代价之间取舍。</p><p>理解取地址、复制、加载和存储四种约束，就能把多级指针关系变成可求解的问题。继续引入控制流、调用上下文、字段和堆抽象，才能逐步接近真实编译器所需的指针模型。</p>',7);function b(h,g){const a=c("RouterLink");return i(),d("div",null,[r,u,s("p",null,[k,n("：计算某个指针可能指向哪些抽象内存对象。上一节的"),e(a,{to:"/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86/2.%E4%B8%AD%E7%AB%AF/(6)%E5%88%AB%E5%90%8D%E5%88%86%E6%9E%90.html"},{default:t(()=>[n("别名分析")]),_:1}),n("则关注两个访问是否可能涉及相同或重叠的内存。指向分析可以为别名分析提供信息，但两者的问题并不完全相同。")]),v,s("p",null,[n("指向结果可以帮助"),e(a,{to:"/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86/2.%E4%B8%AD%E7%AB%AF/(8)%E8%87%AA%E5%8A%A8%E7%9F%A2%E9%87%8F%E5%8C%96.html"},{default:t(()=>[n("自动矢量化")]),_:1}),n("判断不同迭代的读写是否可能冲突，也能支持冗余加载消除、死存储消除、间接调用优化和逃逸分析。但每项优化还需要额外条件，例如控制流、访问大小、操作顺序和可观察副作用。")]),m])}const q=o(l,[["render",b],["__file","(7)指向分析.html.vue"]]);export{q as default};
